const D=window.ALBION_DATA,E=window.CraftEngine,$=id=>document.getElementById(id),cities=['Bridgewatch','Fort Sterling','Lymhurst','Martlock','Thetford','Caerleon','Brecilien'],allCities=[...cities,'Black Market'];
