const KEY='albion-craft-lab-v1';let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}let state=saved||{mode:'food',server:'europe',selected:{food:'T8_MEAL_STEW@1',refine:'T5_CLOTH',bags:'T5_BAG'},drafts:{},overrides:{},quotes:{},histories:{}};let lastResult,currentRecipe;
