function showNotice(s){$('notice').hidden=!s;$('notice').textContent=s}
function quoteRow(id,city,quality=1){return state.quotes[id+'|'+city+'|'+quality]||(state.server==='europe'?D.prices[id+'|'+city+'|'+quality]:null)}
function history(id,city,quality=1){return state.histories[id+'|'+city+'|'+quality]||(state.server==='europe'?D.history[id+'|'+city+'|'+quality]:null)}
