function cheapest(id){let a=cities.map(city=>{const p=quoteRow(id,city);return {city,price:p?.sell_price_min||0,age:age(p?.sell_price_min_date)}}).filter(x=>x.price>0);const fresh=a.filter(x=>x.age<=24);return (fresh.length?fresh:a).sort((a,b)=>a.price-b.price)[0]||{city:'Lymhurst',price:0,age:Infinity}}
