 $('compare').onclick=()=>{let ranked=[];for(const r of D.recipes.filter(x=>x.kind===state.mode)){const c={...cfg,chain:false,unitFee:r.fee300,eff:r.eff};c.rrr=E.returnRate(r.kind,cfg.craftCity,cfg.focus,r.category);for(const city of (state.mode==='bags'?allCities:cities)){const p=quoteRow(r.id,city,cfg.quality),h=history(r.id,city,cfg.quality);const price=cfg.saleMode==='buy'?p?.buy_price_max:p?.sell_price_min;const ts=cfg.saleMode==='buy'?p?.buy_price_max_date:p?.sell_price_min_date;if(!price||age(ts)>24)continue;c.salePrice=cfg.saleMode==='discord'?h?.avg||price:price;const z=E.calculate(r,c,D,cheapest);if(z.missing||z.stale||!z.amount)continue;ranked.push({r,city,z,h})}}ranked.sort((a,b)=>b.z.profit-a.z.profit);$('ranking').innerHTML=ranked.slice(0,18).map(x=>`<tr><td class="name">${esc(x.r.name)}<small>${x.r.tier}.${x.r.ench}</small></td><td>${x.city}</td><td>${fmt(x.z.amount)}</td><td class="${x.z.profit>0?'positive':'negative'}"><b>${money(x.z.profit)}</b></td><td>${x.h?fmt(x.h.daily):'—'}</td><td>${x.h?.daily?fmt(x.z.amount/(x.h.daily*3)*100,1)+'%':'—'}</td><td><button class="button" data-pick="${esc(x.r.id)}" data-sell="${x.city}">Выбрать</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Нет вариантов с полным набором цен моложе 24 часов.</td></tr>'};
